package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.time.*;import java.util.*;import org.bson.Document;import com.mongodb.client.MongoClients;import com.mongodb.client.model.Sorts;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.beans.factory.ObjectProvider;import org.icu.sepsis.integration.*;import org.icu.sepsis.config.RuleConfig;import org.icu.sepsis.domain.ClinicalRules;import org.icu.sepsis.sepsis.SepsisAssessmentService;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
@EnabledIfEnvironmentVariable(named="LOCAL_MONGO_TESTS",matches="1") class LocalMongoDeteriorationTest{
 @Test void realLocalSourceAdapterFeedsMultiOrganWithoutSourceWrites(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var source=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));assertTrue(source.isReadable());var latest=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).first();assertNotNull(latest,"Local observation fixture is required");var patient=source.loadPatient(latest.getString("pid"));var asOf=latest.getDate("time").toInstant();ClinicalDataProvider data=(id,stay,from,to)->source.observations(id,stay,patient.department,from,to);var cfg=new RuleConfig();ObjectProvider<SmartCareSourceReader> reader=mock(ObjectProvider.class);when(reader.getIfAvailable()).thenReturn(source);var assessment=new SepsisAssessmentService(data,new ClinicalRules(cfg),cfg,reader,"smartcare",mock(ObjectProvider.class));var result=new DeteriorationService(data,assessment).read(patient,asOf);assertEquals(patient.id,result.get("patientId"));assertEquals(patient.encounterId,result.get("encounterId"));assertEquals(6,((List<?>)result.get("organs")).size());assertEquals("candidate_review_only",result.get("clinicalUse"));assertNull(result.get("complete"));System.out.println("LOCAL_READONLY_REPLAY: six organ systems; real adapter; retrospective logic only; no source writes");}}

 @Test void actualLocalOxygenWeightAndSedationPathsAreReadWithoutGuessingUnits(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var reader=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));int checked=0;for(String code:List.of("param_FiO2","param_体重","param_score_rass_obs","param_niaoLiang")){var raw=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("code",code).append("valid",true).append("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).maxTime(5,java.util.concurrent.TimeUnit.SECONDS).first();assertNotNull(raw,"Local extra-field fixture required");var patient=reader.loadPatient(raw.getString("pid"));var asOf=raw.getDate("time").toInstant();var rows=reader.observations(patient.id,patient.encounterId,patient.department,asOf.minus(Duration.ofHours(24)),asOf);assertTrue(rows.stream().anyMatch(o->code.equals(o.sourceParameterCode)),"Actual field path must survive the adapter");checked++;}assertEquals(4,checked);System.out.println("LOCAL_EXTRA_FIELDS: oxygen, weight, sedation paths verified; read only; no source writes");}}

 @Test void realSourceQualityReadUsesTheActualAdapterWithoutSourceWrites(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var source=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));var latest=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).first();assertNotNull(latest);var p=source.loadPatient(latest.getString("pid"));var asOf=latest.getDate("time").toInstant();ClinicalDataProvider data=(id,stay,from,to)->source.observations(id,stay,p.department,from,to);var q=new DataQualityService(data,new RuleConfig()).read(p,asOf);assertEquals(p.id,q.get("patientId"));assertEquals(p.encounterId,q.get("encounterId"));assertEquals(true,q.get("available"));assertFalse(((List<?>)q.get("items")).isEmpty());var drugs=new Icu05SourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"),source,"血培养","reviewTime");ObjectProvider<Icu05SourceReader> provider=mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(drugs);var renal=mock(DeteriorationService.class);when(renal.read(any(),any())).thenReturn(Map.of());var medications=new RenalMedicationReviewService(provider,renal).read(p,asOf);assertEquals(p.id,medications.get("patientId"));assertNotEquals("failed",medications.get("sourceStatus"));System.out.println("LOCAL_SOURCE_FEATURES: scoped quality and medication adapters read verified; source read only; renal context separately tested");}}

 @Test void fullLocalDepartmentBatchReconcilesSixOrgansIcu08ReportsAndProneWithoutSourceWrites(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=5000")){var sc=new MongoTemplate(client,"SmartCare");var dc=new MongoTemplate(client,"DataCenter");var source=new SmartCareSourceReader(sc,dc);assertTrue(source.isReadable());String dept="3439";var first=source.listByDept(dept,0,100,"");assertEquals(first.total,first.items.size(),"Current roster fits in one bounded page");var cfg=new RuleConfig();ClinicalDataProvider data=(id,stay,from,to)->source.observations(id,stay,dept,from,to);ObjectProvider<SmartCareSourceReader> sourceProvider=mock(ObjectProvider.class);when(sourceProvider.getIfAvailable()).thenReturn(source);var assessment=new SepsisAssessmentService(data,new ClinicalRules(cfg),cfg,sourceProvider,"smartcare",mock(ObjectProvider.class));var deterioration=new DeteriorationService(data,assessment);var reports=new ArdsReportReader(dc,sc);Instant now=Instant.now();int organs=0,candidates=0,pfSamples=0,reportPatients=0,reportCount=0,pronePatients=0,proneCount=0,failed=0;Map<String,Integer> organStates=new TreeMap<>();Map<String,Integer> icu08States=new TreeMap<>();for(var row:first.items){try{var p=source.loadPatientForDept(String.valueOf(row.get("id")),dept);var risk=deterioration.read(p,now);var os=(List<Map<String,Object>>)risk.get("organs");assertEquals(6,os.size());organs+=os.size();for(var o:os)organStates.merge(String.valueOf(o.get("status")),1,Integer::sum);var icu=source.icu08AdmissionEvidence(p.id,dept);String status=String.valueOf(icu.get("status"));icu08States.merge(status,1,Integer::sum);if("candidate".equals(status))candidates++;if(icu.get("pfSampleCount") instanceof Number)pfSamples+=((Number)icu.get("pfSampleCount")).intValue();var imaging=reports.recent(source.hisPidOf(p.id),now);List<?> reportRows=(List<?>)imaging.getOrDefault("reports",List.of());reportCount+=reportRows.size();if(!reportRows.isEmpty())reportPatients++;var prone=reports.proneSessions(p.id,now);List<?> sessions=(List<?>)prone.getOrDefault("sessions",List.of());proneCount+=sessions.size();if(!sessions.isEmpty())pronePatients++;}catch(RuntimeException e){failed++;}}assertEquals(0,failed,"All listed patients should complete read-only screening");var official=source.icu08OfficialAudit(dept,"2026-10");System.out.println("LOCAL_DEPT_BATCH dept="+dept+" roster="+first.total+" organAssessments="+organs+" organStates="+organStates+" icu08="+icu08States+" admissionCandidates="+candidates+" pfSamples="+pfSamples+" recentReports="+reportCount+" reportPatients="+reportPatients+" proneSessions="+proneCount+" pronePatients="+pronePatients+" failures="+failed+" sourceWrites=0");System.out.println("LOCAL_ICU08_OFFICIAL period="+official.get("period")+" denominator="+official.get("denominator")+" numerator="+official.get("numerator")+" details="+official.get("detailStatus")+" updated="+official.get("updatedAt"));}}

 @Test void monthlyIcu08CohortIsRecountedAgainstOfficialAggregateWithoutPatientIdentifiers(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=5000")){var sc=new MongoTemplate(client,"SmartCare");var source=new SmartCareSourceReader(sc,new MongoTemplate(client,"DataCenter"));String dept="3439";Instant from=Instant.parse("2026-10-01T00:00:00Z"),through=Instant.parse("2026-11-01T00:00:00Z");Document scope=new Document("deptCode",dept).append("status",new Document("$ne","invalid")).append("icuAdmissionTime",new Document("$lt",Date.from(through))).append("$or",List.of(new Document("icuDischargeTime",new Document("$gte",Date.from(from))),new Document("icuDischargeTime",null),new Document("icuDischargeTime",new Document("$exists",false))));var patients=sc.getCollection("patient").find(scope).projection(new Document("_id",1));Map<String,Integer> paths=new TreeMap<>();int cohort=0,candidates=0,errors=0;for(Document d:patients){cohort++;try{var evidence=source.icu08AdmissionEvidence(d.getObjectId("_id").toHexString(),dept);String status=String.valueOf(evidence.get("status"));paths.merge(status,1,Integer::sum);if("candidate".equals(status))candidates++;}catch(RuntimeException e){errors++;}}var official=source.icu08OfficialAudit(dept,"2026-10");var result=source.icu08MonthlyRecompute(dept,"2026-10");assertEquals(3,result.get("recomputedDenominator"));assertEquals(3,((List<?>)result.get("denominatorPatients")).size());assertEquals(0,result.get("sourceErrors"));assertTrue(((Number)result.get("recomputedNumerator")).intValue()>=0);var numRows=(List<Map<String,Object>>)result.get("numeratorPatients");Object firstProneTime=numRows.isEmpty()?null:numRows.get(0).get("firstProneTime"),sourceRecordedAt=numRows.isEmpty()?null:numRows.get(0).get("sourceRecordedAt");System.out.println("LOCAL_ICU08_MONTHLY_RECOUNT period=2026-10 overlapCohort="+cohort+" candidatePath="+candidates+" paths="+paths+" readErrors="+errors+" officialDenominator="+official.get("denominator")+" officialNumerator="+official.get("numerator")+" recomputedNumerator="+result.get("recomputedNumerator")+" firstProneTime="+firstProneTime+" sourceRecordedAt="+sourceRecordedAt+" denominatorCountMatches="+result.get("denominatorCountMatchesOfficial")+" numeratorCountMatches="+result.get("numeratorCountMatchesOfficial")+" detailStatus="+official.get("detailStatus")+" sourceWrites=0");}}
}
